using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace CityForge.Editor {
[InitializeOnLoad] public static class GroundCompositionStudy {
const string Root="Assets/CityForge/Art/Environment/GroundCompositionStudy/";
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/work/";
static Camera camera;static double captureAt;
static GroundCompositionStudy(){EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)return;if(File.Exists(Work+"ground-composition")){File.Delete(Work+"ground-composition");Run();}if(captureAt>0&&EditorApplication.timeSinceStartup>captureAt){captureAt=0;Capture();}}
static float PathX(float z)=>112+18*Mathf.Sin(z*.026f)+.12f*(z-128);
static float Noise(float x,float z,float scale)=>Mathf.PerlinNoise(x/scale+31,z/scale+59);
[MenuItem("CityForge/Ground Study/Ground Composition Zoom 1")]
public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/ForestTreesTrial/ForestTreesMediumZoom1.unity",OpenSceneMode.Single);var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>();camera=UnityEngine.Object.FindFirstObjectByType<Camera>();
var coverage=new float[512,512];var trees=scene.GetRootGameObjects().First(g=>g.name.StartsWith("Forest pack woodland"));foreach(Transform tree in trees.transform){var renderer=tree.GetComponentInChildren<Renderer>();var b=renderer.bounds;if(b.size.y<4)continue;float radius=Mathf.Max(b.extents.x,b.extents.z)*1.15f+3;var center=new Vector2(tree.position.x,tree.position.z);int minX=Mathf.Max(0,Mathf.FloorToInt((center.x-radius)*2)),maxX=Mathf.Min(511,Mathf.CeilToInt((center.x+radius)*2)),minZ=Mathf.Max(0,Mathf.FloorToInt((center.y-radius)*2)),maxZ=Mathf.Min(511,Mathf.CeilToInt((center.y+radius)*2));for(int z=minZ;z<=maxZ;z++)for(int x=minX;x<=maxX;x++){float distance=Vector2.Distance(new Vector2(x*.5f,z*.5f),center);float value=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(radius*.25f,radius,distance));coverage[z,x]=Mathf.Max(coverage[z,x],value);}}
var pixels=new Color[512*512];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=x*.5f,wz=z*.5f;float irregular=(Noise(wx,wz,3)-.5f)*.9f;float distance=Mathf.Abs(wx-PathX(wz))+irregular;float path=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.1f,3.1f,distance));float shoulder=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.5f,5.8f,distance)))*( .4f+.6f*Noise(wx,wz,7));float wood=Mathf.Clamp01(coverage[z,x]+(Noise(wx,wz,6)-.5f)*.25f);pixels[z*512+x]=new Color(wood,path,shoulder,1);}
var mask=new Texture2D(512,512,TextureFormat.RGB24,false,true);mask.SetPixels(pixels);mask.Apply();string maskPath=Root+"GroundCoverage.png";File.WriteAllBytes(maskPath,mask.EncodeToPNG());UnityEngine.Object.DestroyImmediate(mask);AssetDatabase.ImportAsset(maskPath);var ti=(TextureImporter)AssetImporter.GetAtPath(maskPath);ti.sRGBTexture=false;ti.wrapMode=TextureWrapMode.Clamp;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.mipmapEnabled=true;ti.SaveAndReimport();
var material=new Material(Shader.Find("CityForge/Ground Composition Study"));material.SetTexture("_Coverage",AssetDatabase.LoadAssetAtPath<Texture2D>(maskPath));material.SetTexture("_Grass",AssetDatabase.LoadAssetAtPath<Texture2D>(GroundZoom1Study.Art+"Forest1_Albedo.png"));material.SetTexture("_Forest",AssetDatabase.LoadAssetAtPath<Texture2D>(GroundZoom1Study.Art+"Forest2_Albedo.png"));material.SetTexture("_Dirt",AssetDatabase.LoadAssetAtPath<Texture2D>(GroundZoom1Study.Art+"Mud_Albedo.png"));material=Save(material,Root+"GroundComposition.mat");
int n=257;var vertices=new Vector3[n*n];var triangles=new int[(n-1)*(n-1)*6];for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=new Vector3(x,0,z);p.y=terrain.SampleHeight(p);vertices[z*n+x]=p;}int at=0;for(int z=0;z<n-1;z++)for(int x=0;x<n-1;x++){int i=z*n+x;triangles[at++]=i;triangles[at++]=i+n;triangles[at++]=i+1;triangles[at++]=i+1;triangles[at++]=i+n;triangles[at++]=i+n+1;}var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.vertices=vertices;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();mesh=Save(mesh,Root+"GroundMesh.asset");var ground=new GameObject("Ground with meadow, canopy litter and dirt masks");ground.AddComponent<MeshFilter>().sharedMesh=mesh;ground.AddComponent<MeshRenderer>().sharedMaterial=material;terrain.drawHeightmap=false;terrain.enabled=false;
foreach(var root in scene.GetRootGameObjects())if(root.name=="Authored dirt path"||root.name=="Clustered meadow tufts")root.SetActive(false);
var gv=new System.Collections.Generic.List<Vector3>();var gn=new System.Collections.Generic.List<Vector3>();var gt=new System.Collections.Generic.List<int>();UnityEngine.Random.InitState(46023);for(int i=0;i<65000;i++){float x=UnityEngine.Random.Range(5f,251f),z=UnityEngine.Random.Range(5f,251f);int mx=Mathf.Clamp((int)(x*2),0,511),mz=Mathf.Clamp((int)(z*2),0,511);if(pixels[mz*512+mx].r>.35f||pixels[mz*512+mx].g>.05f||Noise(x,z,5)<.43f)continue;float y=terrain.SampleHeight(new Vector3(x,0,z));for(int blade=0;blade<3;blade++){float angle=UnityEngine.Random.value*6.283f;var side=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*.06f;var b=new Vector3(x,y,z);int q=gv.Count;gv.Add(b-side);gv.Add(b+side);gv.Add(b+Vector3.up*UnityEngine.Random.Range(.09f,.23f)+side*.5f);gn.Add(Vector3.up);gn.Add(Vector3.up);gn.Add(Vector3.up);gt.AddRange(new[]{q,q+1,q+2});}}var grassMesh=new Mesh{indexFormat=IndexFormat.UInt32};grassMesh.SetVertices(gv);grassMesh.SetNormals(gn);grassMesh.SetTriangles(gt,0);grassMesh.RecalculateBounds();grassMesh=Save(grassMesh,Root+"ShortMeadowGrass.asset");var grass=new GameObject("Short meadow grass matching ground palette");grass.AddComponent<MeshFilter>().sharedMesh=grassMesh;var gr=grass.AddComponent<MeshRenderer>();var grassMaterial=new Material(material);grassMaterial.SetFloat("_SurfaceScale",.83f);grassMaterial=Save(grassMaterial,Root+"ShortGrass.mat");gr.sharedMaterial=grassMaterial;gr.shadowCastingMode=ShadowCastingMode.Off;
AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"GroundCompositionZoom1.unity");captureAt=EditorApplication.timeSinceStartup+4;Debug.Log("GROUND COMPOSITION READY");}
static T Save<T>(T item,string path) where T:UnityEngine.Object {var old=AssetDatabase.LoadMainAssetAtPath(path);if(old){EditorUtility.CopySerialized(item,old);UnityEngine.Object.DestroyImmediate(item);return (T)old;}else {AssetDatabase.CreateAsset(item,path);return item;}}
static void Capture(){var rt=new RenderTexture(3840,2160,24);rt.Create();var previous=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var image=new Texture2D(3840,2160,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,3840,2160),0,0);image.Apply();File.WriteAllBytes("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/GroundComposition_Zoom1.png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);Debug.Log("GROUND COMPOSITION CAPTURE COMPLETE");}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}}
